['gardu' => ['id_gardu' => '17GD0112000071','no_gardu' => 'WHLWH0729','id_up3' => '17171','up3' => 'TANJUNG KARANG','id_ulp' => '17120','ulp' => 'WAY HALIM','penyulang' => 'GUCCI.','alamat' => '','kode_konstruksi' => 'Gardu Portal','status_pemilik' => '1 - PLN','tahun_pembuatan' => 2017,'merk' => 'UNINDO','no_seri' => '1709022','kapasitas_trafo_kva' => 100], 'pengukuran' => ['beban_trafo_kva' => 31,'beban_trafo_persen' => 31.0,'tegangan_fn_rata2' => 0,'cosphi_rata2' => 0.96,'unbalance_persen' => 5.0,'jam_pengukuran' => '20:29','tanggal_pengukuran' => '2024-12-11','user_input' => 'Inspeksi 1 Way Halim']],
['gardu' => ['id_gardu' => '17GD0112000072','no_gardu' => 'WHLWH0730','id_up3' => '17171','up3' => 'TANJUNG KARANG','id_ulp' => '17120','ulp' => 'WAY HALIM','penyulang' => 'GUCCI.','alamat' => '','kode_konstruksi' => 'Gardu Portal','status_pemilik' => '1 - PLN','tahun_pembuatan' => 2017,'merk' => 'UNINDO','no_seri' => '1709023','kapasitas_trafo_kva' => 100], 'pengukuran' => ['beban_trafo_kva' => 28,'beban_trafo_persen' => 28.0,'tegangan_fn_rata2' => 0,'cosphi_rata2' => 0.96,'unbalance_persen' => 5.0,'jam_pengukuran' => '20:44','tanggal_pengukuran' => '2024-12-11','user_input' => 'Inspeksi 1 Way Halim']],
        ];

        // Flatten if nested (user added chunks)
        $flattenedSamples = [];
        foreach ($samples as $item) {
            if (isset($item['gardu'])) {
                $flattenedSamples[] = $item;
            } else {
                foreach ($item as $subItem) {
                    $flattenedSamples[] = $subItem;
                }
            }
        }

        // A) DATA ARRAY & NORMALIZATION
        // B) DEDUPLIKASI DI DALAM SEEDER
        $byIdGardu = [];
        $skippedCount = 0;
        $renamedNoGarduCount = 0;

        foreach ($flattenedSamples as $row) {
            $idGardu = $this->normalizeString($row['gardu']['id_gardu'] ?? null);
            if (!$idGardu) {
                $skippedCount++;
                continue;
            }

            // Normalisasi data gardu
            $gardu = [
                'id_gardu' => $idGardu,
                'no_gardu' => $this->normalizeString($row['gardu']['no_gardu'] ?? ''),
                'id_up3' => $this->normalizeString($row['gardu']['id_up3'] ?? ''),
                'up3' => $this->normalizeString($row['gardu']['up3'] ?? ''),
                'id_ulp' => $this->normalizeString($row['gardu']['id_ulp'] ?? ''),
                'ulp' => $this->normalizeString($row['gardu']['ulp'] ?? ''),
                'penyulang' => $this->normalizeString($row['gardu']['penyulang'] ?? ''),
                'alamat' => $this->normalizeString($row['gardu']['alamat'] ?? ''),
                'kode_konstruksi' => $this->normalizeString($row['gardu']['kode_konstruksi'] ?? ''),
                'status_pemilik' => $this->normalizeString($row['gardu']['status_pemilik'] ?? ''),
                'tahun_pembuatan' => $this->normalizeNumber($row['gardu']['tahun_pembuatan'] ?? null),
                'merk' => $this->normalizeString($row['gardu']['merk'] ?? ''),
                'no_seri' => $this->normalizeString($row['gardu']['no_seri'] ?? ''),
                'kapasitas_trafo_kva' => $this->normalizeNumber($row['gardu']['kapasitas_trafo_kva'] ?? null),
                'updated_at' => now(),
                'created_at' => now(), // Default if not existing
            ];

            // Normalisasi data pengukuran
            $pengukuran = [
                'beban_trafo_kva' => $this->normalizeNumber($row['pengukuran']['beban_trafo_kva'] ?? null),
                'beban_trafo_persen' => $this->normalizeNumber($row['pengukuran']['beban_trafo_persen'] ?? null),
                'tegangan_fn_rata2' => $this->normalizeNumber($row['pengukuran']['tegangan_fn_rata2'] ?? null),
                'cosphi_rata2' => $this->normalizeNumber($row['pengukuran']['cosphi_rata2'] ?? null),
                'unbalance_persen' => $this->normalizeNumber($row['pengukuran']['unbalance_persen'] ?? null),
                'jam_pengukuran' => $this->normalizeTime($row['pengukuran']['jam_pengukuran'] ?? null),
                'tanggal_pengukuran' => $this->normalizeDate($row['pengukuran']['tanggal_pengukuran'] ?? null),
                'user_input' => $this->normalizeString($row['pengukuran']['user_input'] ?? 'System Seeder'),
                'updated_at' => now(),
                'created_at' => now(),
            ];

            // Map by id_gardu (Overwrite existing logic: ambil yang terakhir muncul di array seeder)
            $byIdGardu[$idGardu] = ['gardu' => $gardu, 'pengukuran' => $pengukuran];
        }

        $totalUnique = count($byIdGardu);
        $this->command->info("Processing {$totalUnique} unique records...");

        // Fetch existing no_gardu mapping from DB for collision check (across all id_gardu)
        $existingNoGarduMap = DB::table('gardus')->pluck('id_gardu', 'no_gardu')->toArray();
        $localNoGarduMap = []; // Track no_gardu mapping within current seeder run

        $finalRows = [];
        foreach ($byIdGardu as $id => $data) {
            $no = $data['gardu']['no_gardu'];
            if (!$no) $no = "GARDU-{$id}";
            
            // Check Collision: If this no_gardu belongs to ANOTHER id_gardu in DB or local map
            $conflictInDB = isset($existingNoGarduMap[$no]) && $existingNoGarduMap[$no] !== $id;
            $conflictLocal = isset($localNoGarduMap[$no]) && $localNoGarduMap[$no] !== $id;

            if ($conflictInDB || $conflictLocal) {
                $newName = $no . "-" . substr($id, -4);
                $data['gardu']['no_gardu'] = $newName;
                $renamedNoGarduCount++;
            }
            
            $localNoGarduMap[$data['gardu']['no_gardu']] = $id;
            $finalRows[] = $data;
        }

        // C, D, E) Processing in Chunks with UPSERT
        $chunks = array_chunk($finalRows, 200);
        $garduUpserted = 0;
        $ukurUpserted = 0;

        foreach ($chunks as $chunk) {
            DB::transaction(function () use ($chunk, &$garduUpserted, &$ukurUpserted) {
                $garduPayload = array_column($chunk, 'gardu');
                $ids = array_column($garduPayload, 'id_gardu');

                // Upsert Gardu (id_gardu as unique key)
                DB::table('gardus')->upsert(
                    $garduPayload,
                    ['id_gardu'],
                    ['no_gardu', 'id_up3', 'up3', 'id_ulp', 'ulp', 'penyulang', 'alamat', 'kode_konstruksi', 'status_pemilik', 'tahun_pembuatan', 'merk', 'no_seri', 'kapasitas_trafo_kva', 'updated_at']
                );
                
                // Fetch Internal ID Mapping
                $idMap = DB::table('gardus')->whereIn('id_gardu', $ids)->pluck('id', 'id_gardu');

                // Prepare Pengukuran Payload
                $ukurPayloads = [];
                foreach ($chunk as $c) {
                    $gId = $idMap[$c['gardu']['id_gardu']] ?? null;
                    if (!$gId) continue;
                    
                    $p = $c['pengukuran'];
                    $p['gardu_id'] = $gId;
                    $ukurPayloads[] = $p;
                }

                if (!empty($ukurPayloads)) {
                    // Upsert Pengukuran (gardu_id + tgl + jam as unique key)
                    DB::table('pengukurans')->upsert(
                        $ukurPayloads,
                        ['gardu_id', 'tanggal_pengukuran', 'jam_pengukuran'],
                        ['beban_trafo_kva', 'beban_trafo_persen', 'tegangan_fn_rata2', 'cosphi_rata2', 'unbalance_persen', 'user_input', 'updated_at']
                    );
                    $ukurUpserted += count($ukurPayloads);
                }
                
                $garduUpserted += count($chunk);
            });
        }

        // G) LOG SUMMARY
        $this->command->info("PLN Seeding Summary:");
        $this->command->table(['Description', 'Count'], [
            ['Total Raw Data', count($flattenedSamples)],
            ['Unique Gardu (id_gardu)', $totalUnique],
            ['Gardu Upserted', $garduUpserted],
            ['Pengukuran Upserted', $ukurUpserted],
            ['No Gardu Renamed (Conflicts)', $renamedNoGarduCount],
            ['Skipped (Empty ID)', $skippedCount]
        ]);
    }

    private function normalizeString($s) {
        if ($s === null) return null;
        $s = trim($s);
        return $s === '' ? null : $s;
    }

    private function normalizeNumber($v) {
        if ($v === null || $v === '') return 0;
        if (is_numeric($v)) return (float) $v;
        $v = str_replace(',', '.', $v);
        $v = preg_replace('/[^0-9.]/', '', $v);
        return (float) ($v ?: 0);
    }

    private function normalizeDate($str) {
        if (!$str) return now()->format('Y-m-d');
        if (preg_match('/^\d{4}-\d{2}-\d{2}$/', $str)) return $str;

        $indonesianMonths = [
            'Januari' => '01', 'Februari' => '02', 'Maret' => '03', 'April' => '04', 'Mei' => '05', 'Juni' => '06',
            'Juli' => '07', 'Agustus' => '08', 'September' => '09', 'Oktober' => '10', 'November' => '11', 'Desember' => '12',
            'Jan' => '01', 'Feb' => '02', 'Mar' => '03', 'Apr' => '04', 'Jun' => '06',
            'Jul' => '07', 'Agu' => '08', 'Sep' => '09', 'Okt' => '10', 'Nov' => '11', 'Des' => '12'
        ];

        // Replace Indonesian months
        foreach ($indonesianMonths as $name => $num) {
            if (stripos($str, $name) !== false) {
                $str = str_ireplace($name, "-{$num}-", $str);
                break;
            }
        }

        try {
            // Remove day name like "Selasa, "
            $clean = preg_replace('/^[a-zA-Z]+,\s+/', '', $str);
            // Fix double dashes from replacement above
            $clean = str_replace('--', '-', $clean);
            return Carbon::parse($clean)->format('Y-m-d');
        } catch (\Exception $e) {
            return now()->format('Y-m-d');
        }
    }

    private function normalizeTime($str) {
        if (!$str) return '00:00';
        try {
            return Carbon::parse($str)->format('H:i');
        } catch (\Exception $e) {
            return '00:00';
        }
    }
}

